-- Populate function-icon booleans on special_cards from image scan output.
-- Generated by src/scripts/scanSpecialFunctionIcons.ts

-- _weighing_ofthe_heart.webp
UPDATE special_cards
SET
  icon_offensive_swords = TRUE,
  icon_defensive_shield = FALSE,
  icon_remainder_of_battle = TRUE,
  icon_remainder_of_game = FALSE,
  icon_attached_paperclip = FALSE,
  icon_astral_plane = TRUE,
  icon_first_action_only = FALSE,
  updated_at = NOW()
WHERE image_path IS NOT NULL AND regexp_replace(image_path, '^.*/', '') = '_weighing_ofthe_heart.webp';

